-- NeoShard initial schema.
-- SPDX-License-Identifier: AGPL-3.0-or-later
--
-- Conventions (docs/replica/architecture.md):
--  * IDs are Snowflakes (BIGINT), generated by the application (ADR-0005).
--  * Times are timestamptz (UTC).
--  * Authorization is enforced in the data layer (server/api/src/authz.rs),
--    not via RLS: the server is the only database client.

-- ---------------------------------------------------------------- accounts
CREATE TABLE users (
    id              BIGINT PRIMARY KEY,
    username        TEXT NOT NULL CHECK (username ~ '^[a-z0-9_.]{2,32}$'),
    display_name    TEXT NOT NULL DEFAULT '' CHECK (length(display_name) <= 64),
    email           TEXT CHECK (email IS NULL OR length(email) <= 254),
    password_hash   TEXT,                         -- NULL for bots and remote users
    avatar          TEXT NOT NULL DEFAULT '',
    flags           BIGINT NOT NULL DEFAULT 0,
    bot             BOOLEAN NOT NULL DEFAULT FALSE,
    instance        TEXT NOT NULL DEFAULT '',     -- '' = local; federated users carry their home domain
    mfa_secret_enc  BYTEA,                        -- AES-256-GCM(nonce || ciphertext)
    mfa_enabled     BOOLEAN NOT NULL DEFAULT FALSE,
    custom_status   TEXT NOT NULL DEFAULT '' CHECK (length(custom_status) <= 128),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at      TIMESTAMPTZ
);
-- Same username may exist on different instances (federation).
CREATE UNIQUE INDEX users_username_uq ON users (instance, username);
CREATE UNIQUE INDEX users_email_uq ON users (lower(email)) WHERE email IS NOT NULL;

CREATE TABLE mfa_backup_codes (
    user_id     BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    code_hash   BYTEA NOT NULL,                   -- SHA-256 of the code (codes are high-entropy)
    used_at     TIMESTAMPTZ,
    PRIMARY KEY (user_id, code_hash)
);

CREATE TABLE sessions (
    id            BIGINT PRIMARY KEY,
    user_id       BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    token_hash    BYTEA NOT NULL UNIQUE,          -- SHA-256 of the bearer token
    device        TEXT NOT NULL DEFAULT '' CHECK (length(device) <= 128),
    ip            TEXT NOT NULL DEFAULT '',
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    last_seen_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    expires_at    TIMESTAMPTZ                     -- NULL = until revoked (bots)
);
CREATE INDEX sessions_user_idx ON sessions (user_id);

-- Short-lived second-step ticket after a password login when 2FA is enabled.
CREATE TABLE mfa_tickets (
    token_hash  BYTEA PRIMARY KEY,
    user_id     BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    device      TEXT NOT NULL DEFAULT '',
    attempts    INT NOT NULL DEFAULT 0,
    expires_at  TIMESTAMPTZ NOT NULL
);
CREATE INDEX mfa_tickets_user_idx ON mfa_tickets (user_id);

CREATE TABLE password_resets (
    token_hash  BYTEA PRIMARY KEY,
    user_id     BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    expires_at  TIMESTAMPTZ NOT NULL,
    used_at     TIMESTAMPTZ
);
CREATE INDEX password_resets_user_idx ON password_resets (user_id);

-- ---------------------------------------------------------------- guilds
CREATE TABLE guilds (
    id          BIGINT PRIMARY KEY,
    name        TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 100),
    icon        TEXT NOT NULL DEFAULT '',
    owner_id    BIGINT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    instance    TEXT NOT NULL DEFAULT '',
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX guilds_owner_idx ON guilds (owner_id);

-- @everyone role has id == guild id and position 0.
CREATE TABLE roles (
    id           BIGINT PRIMARY KEY,
    guild_id     BIGINT NOT NULL REFERENCES guilds(id) ON DELETE CASCADE,
    name         TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 100),
    color        INT NOT NULL DEFAULT 0 CHECK (color BETWEEN 0 AND 16777215),
    position     INT NOT NULL DEFAULT 0 CHECK (position >= 0),
    permissions  BIGINT NOT NULL DEFAULT 0,
    hoist        BOOLEAN NOT NULL DEFAULT FALSE,
    mentionable  BOOLEAN NOT NULL DEFAULT FALSE,
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX roles_guild_idx ON roles (guild_id, position);

CREATE TABLE members (
    guild_id       BIGINT NOT NULL REFERENCES guilds(id) ON DELETE CASCADE,
    user_id        BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    nick           TEXT NOT NULL DEFAULT '' CHECK (length(nick) <= 64),
    joined_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    timeout_until  TIMESTAMPTZ,
    PRIMARY KEY (guild_id, user_id)
);
CREATE INDEX members_user_idx ON members (user_id);

CREATE TABLE member_roles (
    guild_id  BIGINT NOT NULL,
    user_id   BIGINT NOT NULL,
    role_id   BIGINT NOT NULL REFERENCES roles(id) ON DELETE CASCADE,
    PRIMARY KEY (guild_id, user_id, role_id),
    FOREIGN KEY (guild_id, user_id) REFERENCES members(guild_id, user_id) ON DELETE CASCADE
);
CREATE INDEX member_roles_role_idx ON member_roles (role_id);

CREATE TABLE bans (
    guild_id    BIGINT NOT NULL REFERENCES guilds(id) ON DELETE CASCADE,
    user_id     BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    reason      TEXT NOT NULL DEFAULT '' CHECK (length(reason) <= 512),
    banned_by   BIGINT REFERENCES users(id) ON DELETE SET NULL,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (guild_id, user_id)
);

-- ---------------------------------------------------------------- channels
-- type: 1 text, 2 voice, 3 category, 4 announcement, 5 forum, 6 thread, 7 dm, 8 group dm
CREATE TABLE channels (
    id               BIGINT PRIMARY KEY,
    guild_id         BIGINT REFERENCES guilds(id) ON DELETE CASCADE,  -- NULL for DMs
    type             SMALLINT NOT NULL CHECK (type BETWEEN 1 AND 8),
    name             TEXT NOT NULL DEFAULT '' CHECK (length(name) <= 100),
    topic            TEXT NOT NULL DEFAULT '' CHECK (length(topic) <= 1024),
    position         INT NOT NULL DEFAULT 0,
    parent_id        BIGINT REFERENCES channels(id) ON DELETE SET NULL,
    nsfw             BOOLEAN NOT NULL DEFAULT FALSE,
    slowmode_seconds INT NOT NULL DEFAULT 0 CHECK (slowmode_seconds BETWEEN 0 AND 21600),
    last_message_id  BIGINT NOT NULL DEFAULT 0,
    owner_id         BIGINT REFERENCES users(id) ON DELETE SET NULL,
    e2ee             BOOLEAN NOT NULL DEFAULT FALSE,
    archived         BOOLEAN NOT NULL DEFAULT FALSE,
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    CHECK ((type IN (7, 8)) = (guild_id IS NULL))
);
CREATE INDEX channels_guild_idx ON channels (guild_id, position);
CREATE INDEX channels_parent_idx ON channels (parent_id);

-- target_type: 0 role, 1 member
CREATE TABLE permission_overwrites (
    channel_id   BIGINT NOT NULL REFERENCES channels(id) ON DELETE CASCADE,
    target_id    BIGINT NOT NULL,
    target_type  SMALLINT NOT NULL CHECK (target_type IN (0, 1)),
    allow        BIGINT NOT NULL DEFAULT 0,
    deny         BIGINT NOT NULL DEFAULT 0,
    PRIMARY KEY (channel_id, target_id)
);

CREATE TABLE channel_recipients (
    channel_id  BIGINT NOT NULL REFERENCES channels(id) ON DELETE CASCADE,
    user_id     BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    PRIMARY KEY (channel_id, user_id)
);
CREATE INDEX channel_recipients_user_idx ON channel_recipients (user_id);

-- Exactly one 1:1 DM channel per user pair (user_a < user_b).
CREATE TABLE dm_pairs (
    user_a      BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    user_b      BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    channel_id  BIGINT NOT NULL REFERENCES channels(id) ON DELETE CASCADE,
    PRIMARY KEY (user_a, user_b),
    CHECK (user_a < user_b)
);

CREATE TABLE thread_members (
    thread_id  BIGINT NOT NULL REFERENCES channels(id) ON DELETE CASCADE,
    user_id    BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    PRIMARY KEY (thread_id, user_id)
);

CREATE TABLE forum_tags (
    id          BIGINT PRIMARY KEY,
    channel_id  BIGINT NOT NULL REFERENCES channels(id) ON DELETE CASCADE,
    name        TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 32),
    emoji       TEXT NOT NULL DEFAULT ''
);
CREATE INDEX forum_tags_channel_idx ON forum_tags (channel_id);

-- ---------------------------------------------------------------- messages
-- kind: see MessageKind in spec/proto. Hash-partitioned by channel (ADR-0006).
CREATE TABLE messages (
    channel_id        BIGINT NOT NULL,
    id                BIGINT NOT NULL,
    guild_id          BIGINT,
    author_id         BIGINT NOT NULL,
    content           TEXT NOT NULL DEFAULT '' CHECK (length(content) <= 4000),
    kind              SMALLINT NOT NULL DEFAULT 0,
    reply_to_id       BIGINT,
    edited_at         TIMESTAMPTZ,
    pinned            BOOLEAN NOT NULL DEFAULT FALSE,
    mention_everyone  BOOLEAN NOT NULL DEFAULT FALSE,
    mention_user_ids  BIGINT[] NOT NULL DEFAULT '{}',
    mention_role_ids  BIGINT[] NOT NULL DEFAULT '{}',
    attachments       JSONB NOT NULL DEFAULT '[]',
    embeds            JSONB NOT NULL DEFAULT '[]',
    nonce             TEXT CHECK (length(nonce) <= 64),
    webhook_id        BIGINT,
    sticker_id        BIGINT,
    thread_id         BIGINT,
    e2ee_payload      BYTEA,
    tsv               TSVECTOR GENERATED ALWAYS AS (to_tsvector('simple', content)) STORED,
    PRIMARY KEY (channel_id, id),
    -- Idempotent sends: the same (author, nonce) in a channel creates one message.
    UNIQUE (channel_id, author_id, nonce)
) PARTITION BY HASH (channel_id);

DO $$
BEGIN
    FOR i IN 0..15 LOOP
        EXECUTE format('CREATE TABLE messages_p%s PARTITION OF messages FOR VALUES WITH (MODULUS 16, REMAINDER %s)', i, i);
    END LOOP;
END $$;

CREATE INDEX messages_guild_idx ON messages (guild_id, id DESC);
CREATE INDEX messages_author_idx ON messages (author_id, id DESC);
CREATE INDEX messages_pinned_idx ON messages (channel_id) WHERE pinned;
CREATE INDEX messages_tsv_idx ON messages USING GIN (tsv);

CREATE TABLE reactions (
    channel_id  BIGINT NOT NULL,
    message_id  BIGINT NOT NULL,
    emoji       TEXT NOT NULL CHECK (length(emoji) BETWEEN 1 AND 64),
    user_id     BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (message_id, emoji, user_id)
);
CREATE INDEX reactions_channel_idx ON reactions (channel_id, message_id);

CREATE TABLE read_states (
    user_id               BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    channel_id            BIGINT NOT NULL REFERENCES channels(id) ON DELETE CASCADE,
    last_read_message_id  BIGINT NOT NULL DEFAULT 0,
    mention_count         INT NOT NULL DEFAULT 0,
    PRIMARY KEY (user_id, channel_id)
);

CREATE TABLE attachments (
    id            BIGINT PRIMARY KEY,
    uploader_id   BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    channel_id    BIGINT NOT NULL REFERENCES channels(id) ON DELETE CASCADE,
    filename      TEXT NOT NULL CHECK (length(filename) BETWEEN 1 AND 255),
    content_type  TEXT NOT NULL,
    size          BIGINT NOT NULL CHECK (size > 0),
    object_key    TEXT NOT NULL UNIQUE,
    message_id    BIGINT,                        -- NULL until attached to a message
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX attachments_uploader_idx ON attachments (uploader_id, created_at);

-- ---------------------------------------------------------------- guild extras
CREATE TABLE invites (
    code        TEXT PRIMARY KEY CHECK (code ~ '^[A-Za-z0-9]{6,16}$'),
    guild_id    BIGINT NOT NULL REFERENCES guilds(id) ON DELETE CASCADE,
    channel_id  BIGINT NOT NULL REFERENCES channels(id) ON DELETE CASCADE,
    inviter_id  BIGINT REFERENCES users(id) ON DELETE SET NULL,
    max_uses    INT NOT NULL DEFAULT 0 CHECK (max_uses >= 0),
    uses        INT NOT NULL DEFAULT 0 CHECK (uses >= 0),
    expires_at  TIMESTAMPTZ,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    CHECK (max_uses = 0 OR uses <= max_uses)
);
CREATE INDEX invites_guild_idx ON invites (guild_id);

CREATE TABLE audit_log (
    id          BIGINT PRIMARY KEY,
    guild_id    BIGINT NOT NULL REFERENCES guilds(id) ON DELETE CASCADE,
    user_id     BIGINT,                          -- actor; kept after user deletion
    action      TEXT NOT NULL,
    target_id   BIGINT NOT NULL DEFAULT 0,
    changes     JSONB NOT NULL DEFAULT '{}',
    reason      TEXT NOT NULL DEFAULT '' CHECK (length(reason) <= 512),
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX audit_log_guild_idx ON audit_log (guild_id, id DESC);

CREATE TABLE automod_rules (
    id          BIGINT PRIMARY KEY,
    guild_id    BIGINT NOT NULL REFERENCES guilds(id) ON DELETE CASCADE,
    name        TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 100),
    kind        TEXT NOT NULL CHECK (kind IN ('keyword', 'mention_spam', 'link')),
    config      JSONB NOT NULL DEFAULT '{}',
    action      TEXT NOT NULL CHECK (action IN ('block', 'timeout', 'alert')),
    enabled     BOOLEAN NOT NULL DEFAULT TRUE,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX automod_rules_guild_idx ON automod_rules (guild_id);

CREATE TABLE emojis (
    id          BIGINT PRIMARY KEY,
    guild_id    BIGINT NOT NULL REFERENCES guilds(id) ON DELETE CASCADE,
    name        TEXT NOT NULL CHECK (name ~ '^[A-Za-z0-9_]{2,32}$'),
    animated    BOOLEAN NOT NULL DEFAULT FALSE,
    object_key  TEXT NOT NULL,
    created_by  BIGINT REFERENCES users(id) ON DELETE SET NULL,
    UNIQUE (guild_id, name)
);

CREATE TABLE stickers (
    id          BIGINT PRIMARY KEY,
    guild_id    BIGINT NOT NULL REFERENCES guilds(id) ON DELETE CASCADE,
    name        TEXT NOT NULL CHECK (length(name) BETWEEN 2 AND 30),
    format      TEXT NOT NULL CHECK (format IN ('png', 'apng', 'webp', 'lottie')),
    object_key  TEXT NOT NULL,
    UNIQUE (guild_id, name)
);

-- ---------------------------------------------------------------- platform
CREATE TABLE webhooks (
    id          BIGINT PRIMARY KEY,
    guild_id    BIGINT NOT NULL REFERENCES guilds(id) ON DELETE CASCADE,
    channel_id  BIGINT NOT NULL REFERENCES channels(id) ON DELETE CASCADE,
    name        TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 80),
    avatar      TEXT NOT NULL DEFAULT '',
    token_hash  BYTEA NOT NULL,
    created_by  BIGINT REFERENCES users(id) ON DELETE SET NULL,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX webhooks_channel_idx ON webhooks (channel_id);

CREATE TABLE applications (
    id           BIGINT PRIMARY KEY,
    owner_id     BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    bot_user_id  BIGINT NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE,
    name         TEXT NOT NULL CHECK (length(name) BETWEEN 2 AND 32),
    description  TEXT NOT NULL DEFAULT '',
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX applications_owner_idx ON applications (owner_id);

-- guild_id = 0 means a global command.
CREATE TABLE application_commands (
    id              BIGINT PRIMARY KEY,
    application_id  BIGINT NOT NULL REFERENCES applications(id) ON DELETE CASCADE,
    guild_id        BIGINT NOT NULL DEFAULT 0,
    name            TEXT NOT NULL CHECK (name ~ '^[a-z0-9_-]{1,32}$'),
    description     TEXT NOT NULL DEFAULT '' CHECK (length(description) <= 100),
    options         JSONB NOT NULL DEFAULT '[]',
    UNIQUE (application_id, guild_id, name)
);
CREATE INDEX application_commands_guild_idx ON application_commands (guild_id);

CREATE TABLE interactions (
    id              BIGINT PRIMARY KEY,
    application_id  BIGINT NOT NULL REFERENCES applications(id) ON DELETE CASCADE,
    token_hash      BYTEA NOT NULL UNIQUE,
    guild_id        BIGINT,
    channel_id      BIGINT NOT NULL,
    user_id         BIGINT NOT NULL,
    expires_at      TIMESTAMPTZ NOT NULL,
    responded       BOOLEAN NOT NULL DEFAULT FALSE
);

-- ---------------------------------------------------------------- E2EE (MLS)
CREATE TABLE mls_key_packages (
    id           BIGINT PRIMARY KEY,
    user_id      BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    device_id    TEXT NOT NULL CHECK (length(device_id) <= 64),
    key_package  BYTEA NOT NULL CHECK (length(key_package) <= 16384),
    consumed_at  TIMESTAMPTZ,
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX mls_key_packages_available_idx ON mls_key_packages (user_id, id) WHERE consumed_at IS NULL;

-- ---------------------------------------------------------------- push, federation
CREATE TABLE push_subscriptions (
    id          BIGINT PRIMARY KEY,
    user_id     BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    endpoint    TEXT NOT NULL UNIQUE CHECK (length(endpoint) <= 2048),
    p256dh      TEXT NOT NULL,
    auth        TEXT NOT NULL,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX push_subscriptions_user_idx ON push_subscriptions (user_id);

CREATE TABLE federation_instances (
    domain      TEXT PRIMARY KEY,
    public_key  BYTEA NOT NULL,                  -- Ed25519, 32 bytes
    blocked     BOOLEAN NOT NULL DEFAULT FALSE,
    last_seen   TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Replay protection for signed federation requests.
CREATE TABLE federation_nonces (
    origin      TEXT NOT NULL,
    nonce       TEXT NOT NULL,
    seen_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (origin, nonce)
);
